def optimize_matrixcache(out, override):
    path = out / 'managed/Game/SwitchRenderMath.cs'
    text = path.read_text()
    head, tail = text.rsplit('\n}', 1)
    path.write_text(head + '\n\n    internal struct MatrixCache\n    {\n        internal bool Ready;\n        internal Matrix4x4 First, Second, Value;\n    }\n\n    private static bool MatrixBitsEqual(in Matrix4x4 a, in Matrix4x4 b)\n    {\n        var aa = System.Runtime.InteropServices.MemoryMarshal.CreateReadOnlySpan(ref Unsafe.AsRef(in a), 1);\n        var bb = System.Runtime.InteropServices.MemoryMarshal.CreateReadOnlySpan(ref Unsafe.AsRef(in b), 1);\n        return System.Runtime.InteropServices.MemoryMarshal.AsBytes(aa).SequenceEqual(\n            System.Runtime.InteropServices.MemoryMarshal.AsBytes(bb));\n    }\n\n    internal static Matrix4x4 MultiplyCached(in Matrix4x4 a, in Matrix4x4 b, ref MatrixCache cache)\n    {\n        if (cache.Ready && MatrixBitsEqual(a, cache.First) && MatrixBitsEqual(b, cache.Second))\n            return cache.Value;\n        var value = Multiply(a, b);\n        var first = a;\n        var second = b;\n        cache.First = first;\n        cache.Second = second;\n        cache.Value = value;\n        cache.Ready = true;\n        return value;\n    }\n}' + tail)
    override('Graphics/Model.cs', [('public Matrix Transform = Matrix.Identity;', 'public Matrix Transform = Matrix.Identity;\n    internal SwitchRenderMath.MatrixCache WorldMatrixCache;')])
    override('Scenes/World.cs', [('state.ModelMatrix = SwitchRenderMath.Multiply(it.Model.Transform, it.Actor.Matrix);', 'state.ModelMatrix = SwitchRenderMath.MultiplyCached(it.Model.Transform, it.Actor.Matrix, ref it.Model.WorldMatrixCache);')])
